public class RegionalReliefTest{
 public static void main(String[]args){var g=new TerrainGraph();var base=g.add(TerrainGraph.Type.CONSTANT,0,0);base.values.put("height",400.0);var region=g.add(TerrainGraph.Type.REGIONAL_RELIEF,200,0);region.input[0]=base.id;region.values.put("x",50.0);region.values.put("z",50.0);var a=g.evaluate(256,16384,62,2024,region.id,()->false).output();if(a[128*256+128]<399||a[20*256+20]>110)throw new AssertionError("Mountain should be localized above lowland");double maxStep=0;for(int x=1;x<256;x++)maxStep=Math.max(maxStep,Math.abs(a[128*256+x]-a[128*256+x-1]));if(maxStep>40)throw new AssertionError("Abrupt mountain boundary");region.values.put("transition",.8);var wide=g.evaluate(256,16384,62,2024,region.id,()->false).output();double wideStep=0;for(int x=1;x<256;x++)wideStep=Math.max(wideStep,Math.abs(wide[128*256+x]-wide[128*256+x-1]));if(wideStep>=maxStep)throw new AssertionError("Wider foothills should reduce slope");base.values.put("height",40.0);for(float h:g.evaluate(128,16384,62,2024,region.id,()->false).output())if(h!=40)throw new AssertionError("Ocean modified");System.out.println("PASS: localized mountain core, broad lowlands, smooth transition and unchanged ocean");}
}
